const fs = require('node:fs');
const { StringDecoder } = require('node:string_decoder');
const chunks = JSON.parse(fs.readFileSync('data/decoder_chunks.json', 'utf8'));
const decoder = new StringDecoder('utf8');
let text = '';
for (const bytes of chunks) text += decoder.write(Buffer.from(bytes));
text += decoder.end();
console.log(text);
